// Secure Express application with proper error handling and input validation
const express = require('express');
const app = express();

// Security middleware
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting middleware (using built-in memory-based implementation)
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
  next();
});

// Global error handling middleware (must be after all routes)
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(err.status || 500).json({
    error: {
      message: 'Internal server error',
      ...(process.env.NODE_ENV === 'development' && {
        details: err.message,
      }),
    },
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// User endpoint with input validation and sanitization
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { page = 1, limit = 10 } = req.query;

    // Validate page: must be positive integer
    const pageNum = parseInt(page, 10);
    if (isNaN(pageNum) || pageNum < 1) {
      return res.status(400).json({
        error: {
          message: 'Invalid page number. Must be a positive integer.',
          field: 'page',
        },
      });
    }

    // Validate limit: must be positive integer and in range
    const limitNum = parseInt(limit, 10);
    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: {
          message: 'Invalid limit. Must be between 1 and 100.',
          field: 'limit',
        },
      });
    }

    // Simulated user data with pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const result = users.slice(
      (pageNum - 1) * limitNum,
      pageNum * limitNum
    );

    res.json({
      data: result,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: users.length,
      },
    });
  } catch (error) {
    console.error('Error in /users:', error);
    res.status(500).json({
      error: {
        message: 'Failed to fetch users',
      },
    });
  }
});

// Post endpoint with body validation (example)
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return res.status(400).json({
        error: {
          message: 'Name is required and must be a non-empty string.',
          field: 'name',
        },
      });
    }

    if (!email || typeof email !== 'string' || email.trim().length === 0) {
      return res.status(400).json({
        error: {
          message: 'Email is required and must be a non-empty string.',
          field: 'email',
        },
      });
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({
        error: {
          message: 'Invalid email format.',
          field: 'email',
        },
      });
    }

    // Validate name length
    if (name.length > 100) {
      return res.status(400).json({
        error: {
          message: 'Name must not exceed 100 characters.',
          field: 'name',
        },
      });
    }

    // Sanitize inputs
    const sanitizedUser = {
      id: Date.now(), // In production, use a proper ID generator
      name: name.trim(),
      email: email.trim().toLowerCase(),
    };

    // In production, save to database here
    console.log('Created user:', sanitizedUser);

    res.status(201).json({
      message: 'User created successfully',
      data: sanitizedUser,
    });
  } catch (error) {
    console.error('Error in POST /users:', error);
    res.status(500).json({
      error: {
        message: 'Failed to create user',
      },
    });
  }
});

// Start server with proper error handling
const PORT = process.env.PORT || 3000;
app.listen(PORT, (err) => {
  if (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
  console.log(`Secure server running on port ${PORT}`);
});

module.exports = app;

// Validation test script for app.js error handling and input validation
const http = require('http');

// Base configuration
const BASE_URL = 'http://localhost:3000';

// Test cases demonstrating error handling and input validation
const validationTests = [
  {
    name: 'Valid GET request with pagination',
    method: 'GET',
    path: '/users?page=1&limit=10',
    expectedStatus: 200,
  },
  {
    name: 'Invalid page number (negative)',
    method: 'GET',
    path: '/users?page=-1&limit=10',
    expectedStatus: 400,
  },
  {
    name: 'Invalid limit (exceeds max)',
    method: 'GET',
    path: '/users?page=1&limit=101',
    expectedStatus: 400,
  },
  {
    name: 'Invalid limit (non-numeric)',
    method: 'GET',
    path: '/users?page=1&limit=ten',
    expectedStatus: 400,
  },
  {
    name: 'Valid POST request with user data',
    method: 'POST',
    path: '/users',
    body: JSON.stringify({
      name: 'John Doe',
      email: 'john@example.com'
    }),
    expectedStatus: 201,
  },
  {
    name: 'Missing name field',
    method: 'POST',
    path: '/users',
    body: JSON.stringify({
      email: 'john@example.com'
    }),
    expectedStatus: 400,
  },
  {
    name: 'Missing email field',
    method: 'POST',
    path: '/users',
    body: JSON.stringify({
      name: 'Jane Smith'
    }),
    expectedStatus: 400,
  },
  {
    name: 'Invalid email format',
    method: 'POST',
    path: '/users',
    body: JSON.stringify({
      name: 'Test User',
      email: 'invalid-email'
    }),
    expectedStatus: 400,
  },
  {
    name: 'Empty name field',
    method: 'POST',
    path: '/users',
    body: JSON.stringify({
      name: '   ',
      email: 'test@example.com'
    }),
    expectedStatus: 400,
  },
  {
    name: 'Name exceeds maximum length',
    method: 'POST',
    path: '/users',
    body: JSON.stringify({
      name: 'A'.repeat(101),
      email: 'test@example.com'
    }),
    expectedStatus: 400,
  },
  {
    name: 'SQL injection attempt in name',
    method: 'POST',
    path: '/users',
    body: JSON.stringify({
      name: "'; DROP TABLE users; --",
      email: 'test@example.com'
    }),
    expectedStatus: 201, // Should be sanitized and prevented from DB injection
  },
  {
    name: 'XSS attempt in name',
    method: 'POST',
    path: '/users',
    body: JSON.stringify({
      name: '<script>alert("XSS")</script>',
      email: 'test@example.com'
    }),
    expectedStatus: 201, // Should be sanitized
  },
];

// Send HTTP request and return result
function makeRequest(test) {
  return new Promise((resolve) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: test.path,
      method: test.method,
      headers: {
        'Content-Type': 'application/json',
        ...(test.body && { 'Content-Length': Buffer.byteLength(test.body) }),
      },
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          const parsedData = JSON.parse(data);
          resolve({
            ...test,
            actualStatus: res.statusCode,
            response: parsedData,
            passed: res.statusCode === test.expectedStatus,
          });
        } catch (e) {
          resolve({
            ...test,
            actualStatus: res.statusCode,
            response: data,
            passed: false,
          });
        }
      });
    });

    req.on('error', (error) => {
      resolve({
        ...test,
        actualStatus: 0,
        error: error.message,
        passed: false,
      });
    });

    if (test.body) {
      req.write(test.body);
    }

    req.end();
  });
}

// Run all tests
async function runTests() {
  console.log('🧪 Running Validation Tests for app.js\n');
  console.log('='.repeat(60));

  const results = [];
  let passedCount = 0;

  for (const test of validationTests) {
    const result = await makeRequest(test);
    results.push(result);

    if (result.passed) {
      passedCount++;
      console.log(`✅ ${test.name}`);
    } else {
      console.log(`❌ ${test.name}`);
      console.log(`   Expected: ${test.expectedStatus}, Got: ${result.actualStatus}`);
      if (result.error) {
        console.log(`   Error: ${result.error}`);
      }
    }
  }

  console.log('='.repeat(60));
  console.log(`\n📊 Test Results: ${passedCount}/${validationTests.length} passed`);

  if (passedCount === validationTests.length) {
    console.log('✅ All validation tests passed!');
  } else {
    console.log(`⚠️  ${validationTests.length - passedCount} tests failed`);
  }
}

// Check if server is running
function checkServer() {
  return new Promise((resolve) => {
    http.get(`${BASE_URL}/health`, (res) => {
      resolve(true);
    }).on('error', () => {
      resolve(false);
    });
  });
}

// Main execution
(async () => {
  const serverRunning = await checkServer();
  if (!serverRunning) {
    console.error('❌ Server is not running on port 3000');
    console.error('Please start the server with: node app.js');
    process.exit(1);
  }
  console.log('✅ Server is running, starting tests...\n');
  await runTests();
})();

