// Security Hardened Express Application
// Built with defense-in-depth principles

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const validator = require('validator');
const winston = require('winston');
const path = require('path');

// Initialize Express app
const app = express();

// Secure defaults with Helmet (XSS, CSRF, clickjacking protection)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: []
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate Limiting - Prevent DDoS and abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests, please try again later'
  },
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many requests, please try again later' });
  }
});

// Apply rate limiting to all routes except health check
app.use(limiter);

// CORS Configuration - Restrict origins
const corsOptions = {
  origin: process.env.NODE_ENV === 'production'
    ? ['https://yourdomain.com', 'https://app.yourdomain.com']
    : '*', // Allow dev origins in development
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Custom-Header'],
  credentials: true,
  maxAge: 86400
};

app.use(cors(corsOptions));

// Body parsing with size limits
app.use(express.json({
  limit: '10kb', // Limit request size to 10KB
  verify: (req, res, buf) => {
    // Detect unicode bom and null bytes for potential injection
    if (buf && buf.length > 0) {
      const bomWarning = '\uFEFF' === buf.toString('utf8', 0, 1);
      if (bomWarning) {
        logger.warn(`Potential BOM detected in request from ${req.ip}`);
      }
    }
  }
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Request logging middleware
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const requestLogger = (req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip
    });
  });
  next();
};
app.use(requestLogger);

// Custom error handler
app.use((err, req, res, next) => {
  if (err.validationErrors) {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.validationErrors
    });
  }

  logger.error(err.stack || err.message, {
    method: req.method,
    url: req.url,
    ip: req.ip
  });

  // In production, don't leak stack traces
  res.status(500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message || 'An unexpected error occurred'
  });
});

// Logging middleware - PII scrubbing
const sanitizeLogger = (req, res, next) => {
  // Simplified PII scrubbing
  const sanitized = { ...req.body };
  const sensitiveFields = ['password', 'token', 'secret', 'apiKey', 'api_key'];
  sensitiveFields.forEach(field => {
    if (sanitized[field]) {
      sanitized[field] = '[REDACTED]';
    }
  });
  next();
};
app.use(sanitizeLogger);

// Validation middleware helper
const validate = (validations) => {
  return async (req, res, next) => {
    for (const validation of validations) {
      const result = await validation.run(req);
      if (!result.isEmpty()) {
        return next({
          validationErrors: result.array(),
          status: 400
        });
      }
    }
    next();
  };
};

// ===================================================================
// ROUTES
// ===================================================================

// Health check endpoint - No rate limit, well controlled input
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: '1.0.0'
  });
});

// Get users endpoint with validation
app.get('/users', (req, res) => {
  // Query parameter validation
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;

  // Basic validation for query parameters
  if (page < 1) {
    return res.status(400).json({ error: 'Page must be a positive integer' });
  }
  if (limit > 100) {
    return res.status(400).json({ error: 'Limit cannot exceed 100' });
  }

  res.json({
    page,
    limit,
    users: [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ]
  });
});

// POST /users endpoint with full validation
app.post('/users',
  [
    // Validation rules
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
      .escape(), // XSS protection

    body('email')
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail()
      .escape(), // XSS protection

    body('password')
      .optional()
      .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
      .matches(/[A-Z]/).withMessage('Password must contain at least one uppercase letter')
      .matches(/[a-z]/).withMessage('Password must contain at least one lowercase letter')
      .matches(/[0-9]/).withMessage('Password must contain at least one number')
      .matches(/[^A-Za-z0-9]/).withMessage('Password must contain at least one special character')
  ],
  validate,
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }

    // Additional business logic validation
    const user = {
      id: Date.now(), // In production, use proper ID generation
      name: req.body.name,
      email: req.body.email,
      createdAt: new Date().toISOString()
    };

    logger.info('User created', { email: req.body.email });

    res.status(201).json({
      success: true,
      data: user
    });
  }
);

// ===================================================================
// ERROR HANDLING
// ===================================================================

// JSON parsing error handling
app.use((err, req, res, next) => {
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON in request body',
      message: err.message
    });
  }
  next(err);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.url} not found`
  });
});

// Start server with error handling
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);

  if (NODE_ENV !== 'production') {
    console.log(`  => Local:   http://localhost:${PORT}`);
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

