#!/usr/bin/env node

/**
 * Configuration Validation Script
 *
 * This script validates the YAML/YML configuration by checking:
 * 1. Environment variable syntax and format
 * 2. URL validity (schema, format)
 * 3. Basic credential patterns
 *
 * NOTE: This script does NOT attempt to:
 * - Connect to databases
 * - Call APIs
 * - Validate credentials by testing authentication
 * - Expose or leak any credentials
 */

const fs = require('fs');
const path = require('path');
const { URL } = require('url');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m'
};

// Log helper functions
function log(level, message) {
  const timestamp = new Date().toISOString();
  switch (level) {
    case 'info':
      console.log(`${colors.cyan}[INFO]${colors.reset} [${timestamp}] ${message}`);
      break;
    case 'success':
      console.log(`${colors.green}[SUCCESS]${colors.reset} [${timestamp}] ${message}`);
      break;
    case 'error':
      console.log(`${colors.red}[ERROR]${colors.reset} [${timestamp}] ${message}`);
      break;
    case 'warning':
      console.log(`${colors.yellow}[WARNING]${colors.reset} [${timestamp}] ${message}`);
      break;
  }
}

/**
 * Check if a file exists
 */
function fileExists(filePath) {
  try {
    return fs.existsSync(filePath) && fs.statSync(filePath).isFile();
  } catch (err) {
    return false;
  }
}

/**
 * Parse PostgreSQL URL
 * Validates the syntax but does NOT attempt to connect
 */
function validatePostgresUrl(postgresUrl) {
  if (!postgresUrl) {
    return { valid: false, reason: 'URL is missing' };
  }

  try {
    // Basic URL format validation
    const url = new URL(postgresUrl);

    if (url.protocol !== 'postgres:' && url.protocol !== 'postgresql:') {
      return { valid: false, reason: `Invalid protocol: expected postgres:, got ${url.protocol}` };
    }

    if (!url.username) {
      return { valid: false, reason: 'Username is missing' };
    }

    if (!url.password) {
      return { valid: false, reason: 'Password is missing' };
    }

    if (!url.host) {
      return { valid: false, reason: 'Database host is missing' };
    }

    if (!url.port) {
      return { valid: true, warnings: ['Port is not specified, defaults will be used'] };
    }

    return { valid: true, warnings: [] };
  } catch (err) {
    return { valid: false, reason: `Invalid PostgreSQL URL format: ${err.message}` };
  }
}

/**
 * Validate AWS credentials
 * Only checks format, not validity through AWS API
 */
function validateAwsCredentials(accessKey, secretKey) {
  const errors = [];
  const warnings = [];

  if (!accessKey) {
    errors.push('AWS_ACCESS_KEY_ID is missing');
  } else if (!/^[A-Z0-9]{20}$/.test(accessKey)) {
    errors.push('AWS_ACCESS_KEY_ID appears invalid (expected 20 alphanumeric chars)');
  } else {
    warnings.push('AWS_ACCESS_KEY_ID format validation passed');
  }

  if (!secretKey) {
    errors.push('AWS_SECRET_ACCESS_KEY is missing');
  } else if (!/^[A-Za-z0-9/+=]{40}$/.test(secretKey)) {
    errors.push('AWS_SECRET_ACCESS_KEY appears invalid (expected 40 alphanumeric chars)');
  } else {
    warnings.push('AWS_SECRET_ACCESS_KEY format validation passed');
  }

  return { valid: errors.length === 0, errors, warnings };
}

/**
 * Validate Anthropic API key format
 */
function validateAnthropicKey(apiKey) {
  if (!apiKey) {
    return { valid: false, reason: 'ANTHROPIC_API_KEY is missing' };
  }

  // Format: sk-ant- followed by additional characters
  if (!/^sk-ant-[a-zA-Z0-9_-]+$/.test(apiKey)) {
    return { valid: false, reason: 'ANTHROPIC_API_KEY format appears invalid (expected sk-ant- prefix)' };
  }

  return { valid: true, warnings: ['Format validation passed'] };
}

/**
 * Validate Stripe API key format
 */
function validateStripeKey(apiKey) {
  if (!apiKey) {
    return { valid: false, reason: 'STRIPE_SECRET_KEY is missing' };
  }

  // Format: sk_live_ or sk_test_ followed by octets
  if (!/^sk_[a-z]+_[a-zA-Z0-9_]+$/.test(apiKey)) {
    return { valid: false, reason: 'STRIPE_SECRET_KEY format appears invalid (expected sk_live_ or sk_test_ prefix)' };
  }

  return { valid: true, warnings: ['Format validation passed'] };
}

/**
 * Validate Logfire token
 */
function validateLogfireToken(token) {
  if (!token) {
    return { valid: false, reason: 'LOGFIRE_TOKEN is missing' };
  }

  // Various possible token patterns
  const patterns = [
    /^[a-z0-9]{36}$/,           // UUID-like: 36 lowercase alphanumeric
    /^[a-z0-9]{32}$/,           // 32 alphanumeric hex
    /^[a-z0-9_-]{40,100}$/      // Long alphanumeric/hyphen/underscore
  ];

  const matchesPattern = patterns.some(pattern => pattern.test(token));

  if (!matchesPattern) {
    return { valid: false, reason: 'LOGFIRE_TOKEN format appears invalid' };
  }

  return { valid: true, warnings: ['Format validation passed (pattern matched)'] };
}

/**
 * Read environment variables from file
 */
function readEnvFile(filePath) {
  if (!fileExists(filePath)) {
    return null;
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    // Skip comments and empty lines
    if (!line.trim() || line.startsWith('#')) return;

    // Parse KEY=VALUE
    const match = line.match(/^([^=#]+)=(.*)$/s);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Validate强度的环境变量内容
 */
function validateCredentials(envVars) {
  const results = {};

  // PostgreSQL URL validation
  if (envVars['DATABASE_URL']) {
    results['DATABASE_URL'] = validatePostgresUrl(envVars['DATABASE_URL']);
  }

  // AWS credentials validation
  if (envVars['AWS_ACCESS_KEY_ID']) {
    results['AWS_ACCESS_KEY_ID'] = validateAwsCredentials(
      envVars['AWS_ACCESS_KEY_ID'],
      envVars['AWS_SECRET_ACCESS_KEY'] || ''
    );
  }

  // Anthropic API key validation
  if (envVars['ANTHROPIC_API_KEY']) {
    results['ANTHROPIC_API_KEY'] = validateAnthropicKey(envVars['ANTHROPIC_API_KEY']);
  }

  // Stripe API key validation
  if (envVars['STRIPE_SECRET_KEY']) {
    results['STRIPE_SECRET_KEY'] = validateStripeKey(envVars['STRIPE_SECRET_KEY']);
  }

  // Logfire token validation
  if (envVars['LOGFIRE_TOKEN']) {
    results['LOGFIRE_TOKEN'] = validateLogfireToken(envVars['LOGFIRE_TOKEN']);
  }

  return results;
}

/**
