// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
    },
  },
}));

// Morgan for HTTP request logging (development only)
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter); // Apply rate limiting to API routes

// ============================================
// BODY PARSING WITH SIZE LIMITS
// ============================================

// Limit request body size (prevent OOM attacks)
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// ============================================
// REQUEST VALIDATION
// ============================================

// Validation utilities
const validators = {
  // Simple email validation
  email: (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  },

  // Basic ID validation (positive integers)
  id: (id) => {
    const num = parseInt(id, 10);
    return !isNaN(num) && num >= 0 && Number.isInteger(num);
  },

  // Name validation (letters, spaces, hyphens, apostrophes only)
  name: (name) => {
    if (!name || typeof name !== 'string') return false;
    const nameRegex = /^[a-zA-Z\s'-]+$/;
    return nameRegex.test(name.trim()) && name.trim().length >= 2;
  },
};

// Validation middleware to be reused across routes
const validateRequest = (validators) => {
  return (req, res, next) => {
    const errors = [];

    for (const [field, validator] of Object.entries(validators)) {
      const value = req.query[field] || req.params[field] || req.body?.[field];

      // Skip validation if field is not present (optional fields)
      if (value === undefined || value === null) continue;

      try {
        if (!validator(value)) {
          errors.push({
            field,
            message: `${field} validation failed`,
            providedValue: value,
          });
        }
      } catch (error) {
        errors.push({
          field,
          message: `Error validating ${field}`,
          error: error.message,
        });
      }
    }

    if (errors.length > 0) {
      const errorResponse = {
        success: false,
        errors: errors,
        timestamp: new Date().toISOString(),
      };

      // Use HTTP 400 Bad Request for validation errors
      return res.status(400).json(errorResponse);
    }

    next();
  };
};

// ============================================
// ERROR HANDLING
// ============================================

// Global error handling middleware
// Order matters - this must come after all routes
app.use((err, req, res, next) => {
  // Log the error for debugging (production)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  // Map errors to appropriate status codes
  const statusCode = err.statusCode || 500;

  // Don't expose stack traces in production
  const response = {
    success: false,
    error: {
      message:
        statusCode === 500
          ? 'Internal server error'
          : err.message || 'An error occurred',
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    },
    timestamp: new Date().toISOString(),
    path: req.path,
  };

  res.status(statusCode).json(response);
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint (no authentication needed)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: process.env.npm_package_version || '1.0.0',
  });
});

// Users endpoint with validation example
app.get('/users', (req, res) => {
  try {
    // Example of how to validate query parameters
    const userId = req.query.id;
    const email = req.query.email;

    // There's no validation for this specific endpoint
    // since users[] endpoint has no parameters.
    // But the pattern could be used if needed:

    // if (userId && !validators.id(userId)) {
    //   return res.status(400).json({
    //     success: false,
    //     error: 'Invalid user ID',
    //   });
    // }

    // Return user data (in real app, fetch from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Optional: filter by ID if provided
    if (userId) {
      const filtered = users.filter(u => u.id === parseInt(userId, 10));
      return res.json(filtered.length > 0 ? filtered : []);
    }

    res.json(users);
  } catch (error) {
    // Errors are handled by global error handler
    return next(error);
  }
});

// Example validating POST request body
app.post('/simulate-validation', validateRequest({
  email: validators.email,
  name: validators.name,
}), (req, res) => {
  res.json({
    success: true,
    data: {
      email: req.body.email,
      name: req.body.name,
    },
    message: 'Validation successful',
    timestamp: new Date().toISOString(),
  });
});

// ============================================
// START SERVER
// ============================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Health check: http://localhost:${PORT}/health`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
  process.exit(0);
});

module.exports = app;

