app.use(helmet());

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Body parser configuration
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.url}`);
  next();
});

// Custom error class for application errors
class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle AppError instances
  if (err instanceof AppError) {
    return res.status(err.statusCode).json({
      error: err.message,
      status: err.statusCode
    });
  }

  // Handle other errors
  res.status(500).json({
    error: 'Internal server error',
    status: 500
  });
});

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    status: 404
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with validation
app.get('/users', [
  // Validate query parameters
  param('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  param('email')
    .optional()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format')
], (req, res, next) => {
  // Validate input
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }

  // Data would typically come from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter user if ID is provided
  let filteredUsers = users;
  if (req.query.id) {
    const userId = parseInt(req.query.id, 10);
    filteredUsers = users.filter(user => user.id === userId);
    if (filteredUsers.length === 0) {
      return res.status(404).json({
        error: 'User not found',
        status: 404
      });
    }
  }

  res.json(filteredUsers);
});

// Create user endpoint with validation
app.post('/users', [
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ max: 100 })
    .withMessage('Name must be less than 100 characters')
    .escape(), // Prevent XSS
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
  body('age')
    .optional()
    .isInt({ min: 1, max: 150 })
    .withMessage('Age must be between 1 and 150')
], (req, res, next) => {
  // Validate input
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }

  // Process user data
  const newUser = {
    id: users.length + 1,
    ...req.body,
    createdAt: new Date().toISOString()
  };

  // In real app: validate unique email, save to DB, etc.
  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
});

// Route parameter validation example
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
], (req, res, next) => {
  // Validate input
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }

  const userId = parseInt(req.params.id, 10);

  // Simulated database lookup
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
