const express = require('express');
const helmet = require('helmet'); // Security middleware
const rateLimit = require('express-rate-limit'); // Rate limiting
const xss = require('xss-clean'); // XSS protection
const cors = require('cors'); // CORS configuration
const validator = require('validator');
const app = express();

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply security middleware
app.use(helmet());
app.use(xss());
app.use(limiter);

// CORS configuration - modify origins as needed
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Parse JSON body
app.use(express.json());

// Simple validation for email format
const isValidEmail = (email) => {
  if (!email) return false;
  try {
    return validator.isEmail(email.trim());
  } catch (err) {
    return false;
  }
};

// Health endpoint
app.get('/health', (req, res) => {
  try {
    // Validate the request is GET
    if (req.method !== 'GET') {
      const error = new Error('Method not allowed');
      error.status = 405;
      throw error;
    }

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (err) {
    next(err);
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate request method
    if (req.method !== 'GET') {
      const error = new Error('Method not allowed');
      error.status = 405;
      throw error;
    }

    // Validate query parameters if present
    if (req.query.email) {
      if (!isValidEmail(req.query.email)) {
        const error = new Error('Invalid email format');
        error.status = 400;
        throw error;
      }
    }

    // Return users (in production, this should come from a database)
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (err) {
    next(err);
  }
});

// Error handling middleware - must be last
app.use((err, req, res, next) => {
  console.error('[Error]', {
    message: err.message,
    status: err.status || 500,
    path: req.path,
    method: req.method,
    error: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  res.status(err.status || 500).json({
    error: err.status === 400 ? 'Bad Request' :
           err.status === 401 ? 'Unauthorized' :
           err.status === 403 ? 'Forbidden' :
           err.status === 404 ? 'Not Found' :
           err.status === 429 ? 'Too Many Requests' :
           'Internal Server Error',
    message: err.message || 'An unexpected error occurred',
    ...(process.env.NODE_ENV === 'development' ? { stack: err.stack } : {})
  });
});

// 404 handler - must be after all routes
app.use((req, res) => {
  const error = new Error('Not Found');
  error.status = 404;
  next(error);
});

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

