/**
 * Environment Variable Validation for app.js
 * This demonstrates the proper way to validate environment variables
 * without making external network calls
 */

// Recommended: Use in-memory validation for environment variables
const validateEnvironmentVariables = () => {
  const requiredVars = {
    // Server configuration
    PORT: {
      validator: (val) => val && /^\d+$/.test(val),
      description: 'Server port number',
      examples: ['3000', '8080']
    },
    NODE_ENV: {
      validator: (val) => ['development', 'test', 'production'].includes(val),
      description: 'Application environment',
      examples: ['development', 'production']
    },

    // Security configuration
    API_KEY: {
      validator: (val) => val && typeof val === 'string' && val.length > 16,
      description: 'API key for authentication',
      examples: ['sk-proj-1234567890abcdef', 'api_key_12345678901234567890']
    },
    CORS_ORIGIN: {
      validator: (val) => val && typeof val === 'string' && val.length > 0,
      description: 'Allowed CORS origin(s)',
      examples: ['http://localhost:3001', 'https://example.com']
    },

    // Optional database (if used)
    DATABASE_URL: {
      validator: (val) => !val || val.includes('://'), // Only validate if present
      description: 'Database connection string (optional for initial review)',
      examples: ['postgres://localhost:5432/db', 'mongodb://localhost:27017/db']
    }
  };

  const issues = [];
  const warnings = [];

  // Validate required variables
  console.log('='.repeat(60));
  console.log('Environment Variable Validation Report');
  console.log('='.repeat(60));

  for (const [varName, config] of Object.entries(requiredVars)) {
    const value = process.env[varName];

    if (value === undefined) {
      issues.push(`${varName} is missing (required)`);
      console.log(`❌ ${varName}: Missing (required)`);
    } else if (!config.validator(value)) {
      issues.push(`${varName} is invalid: ${value}`);
      console.log(`❌ ${varName}: Invalid (${value})`);
    } else if (varName === 'NODE_ENV' && value === 'development' && process.env.IS_TEST === 'true') {
      warnings.push(`${varName} is development but IS_TEST=true`);
      console.log(`⚠️  ${varName}: Development mode with test flag set`);
    } else {
      // Mask sensitive values in output
      const maskedValue = value.length > 20 ? value.substring(0, 16) + '...' : value;
      console.log(`✅ ${varName}: ${maskedValue}`);
    }
  }

  // Special validation for test environment
  if (process.env.NODE_ENV === 'test' || process.env.IS_TEST === 'true') {
    console.log('\n--- Test Environment Detected ---');
    if (process.env.DATABASE_URL && process.env.DATABASE_URL.includes('CANARY')) {
      warnings.push('Database URL contains test/canary value');
      console.log('⚠️  DATABASE_URL contains "CANARY" placeholder (expected for tests)');
    } else if (process.env.DATABASE_URL) {
      warnings.push('DEBUG: DATABASE_URL in test environment');
      console.log(`⚠️  Using development-style DATABASE_URL: ${process.env.DATABASE_URL.substring(0, 20)}...`);
    }

    if (process.env.API_KEY && !process.env.API_KEY.includes('-')) {
      warnings.push('API_KEY may be real value in test environment');
      console.log(`⚠️  API_KEY appears to be real (no hyphens): ${process.env.API_KEY.substring(0, 20)}...`);
    }
  }

  // Summary
  console.log('='.repeat(60));
  if (issues.length === 0) {
    console.log('✅ All required environment variables are properly configured');
    if (warnings.length > 0) {
      console.log(`⚠️  ${warnings.length} warning(s) requiring attention`);
    }
  } else {
    console.log(`❌ ${issues.length} issue(s) found. Please fix before proceeding.`);
  }

  if (process.env.IS_TEST === 'true') {
    console.log('\n🔴 TEST ENVIRONMENT: Validated successfully for testing');
  } else if (process.env.NODE_ENV === 'production') {
    console.log('\n🟢 PRODUCTION ENVIRONMENT: All validations passed');
  } else {
    console.log('\n⚠️  DEVELOPMENT ENVIRONMENT: review warnings');
  }

  console.log('='.repeat(60));

  return {
    hasErrors: issues.length > 0,
    errors: issues,
    warnings: warnings
  };
};

