const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const mongoDistance = require('mongo-distance/dist/index');

const app = express();

// ========== SECURITY MIDDLEWARE ==========
// Helmet sets various HTTP headers to secure the Express app
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", 'https://fonts.googleapis.com'],
      scriptSrc: ["'self'", 'https://js.stripe.com/v3/'],
      imgSrc: ["'self'", 'data:', 'https://picsum.photos'],
      connectSrc: ["'self'"],
    },
  },
  xssFilter: true,
  noSniff: true,
  noCache: false,
  hidePoweredBy: true,
}));

// Rate limiting to prevent abuse
const rateLimitOptions = {
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests, please try again later.',
    retryAfter: 15
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json(rateLimitOptions.message).end();
  },
};
app.use('/api/', rateLimit(rateLimitOptions));

// Input sanitization and validation
app.use(xss()); // XSS protection
app.use(mongoSanitize()); // NoSQL injection protection
app.use(express.json({ limit: '10kb' })); // Body size limit
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Request logging middleware
const requestLogger = (req, res, next) => {
  const { method, url, ip } = req;
  console.log(`[${new Date().toISOString()}] ${method} ${url} - ${ip}`);
  next();
};
app.use(requestLogger);

// ========== PUBLIC ENDPOINTS ==========

// Health check - rate limited and with proper validation
app.get('/health', (req, res) => {
  try {
    const timestamp = new Date().toISOString();
    const checks = [];

    // Basic health checks
    if (req.headers['x-request-time']) {
      checks.push({ component: 'header_validation', status: 'valid' });
    }

    res.status(200).json({
      status: 'ok',
      timestamp,
      checks,
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      status: 'error'
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset } = req.query;

    // Validate limit: must be a positive integer <= 100
    const validLimit = limit
      ? Math.min(Math.max(parseInt(limit) || 10, 1), 100)
      : 10;

    // Validate offset: must be a non-negative integer
    const validOffset = Math.max(parseInt(offset) || 0, 0);

    console.log(`Fetching users: limit=${validLimit}, offset=${validOffset}`);

    // Simulate response (in production, this would come from a database)
    const users = Array.from({ length: Math.min(validLimit, 3) }, (_, i) => ({
      id: i,
      name: ['Alice', 'Bob', 'Charlie'][i],
      email: [`${['alice', 'bob', 'charlie'][i]}@example.com`][i]
    }));

    res.status(200).json({
      data: users,
      pagination: {
        limit: validLimit,
        offset: validOffset,
        total: 3,
        hasMore: validOffset + validLimit < 3
      }
    });
  } catch (error) {
    console.error('Error fetching users:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to retrieve user data'
    });
  }
});

// Authentication example endpoint (unauthenticated, for demonstration)
app.post('/api/login', (req, res) => {
  try {
    const { email, password } = req.body;

    // Validate required fields
    if (!email || !password) {
      return res.status(400).json({
        error: 'Validation error',
        message: 'Email and password are required'
      });
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({
        error: 'Validation error',
        message: 'Invalid email format'
      });
    }

    // Validate password length
    if (password.length < 8) {
      return res.status(400).json({
        error: 'Validation error',
        message: 'Password must be at least 8 characters'
      });
    }

    // In production: Validate against database, check credentials, etc.
    res.status(400).json({
      error: 'Unauthorized',
      message: 'Invalid credentials'
    });
  } catch (error) {
    console.error('Login attempt error:', error.message);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Login process failed'
    });
  }
});

// Error handling middleware (must be last)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Log detailed error for development
  if (process.env.NODE_ENV === 'development') {
    res.status(err.status || 500).json({
      error: err.message || 'Internal server error',
      stack: err.stack
    });
  } else {
    // Production: don't expose stack traces
    res.status(err.status || 500).json({
      error: 'Internal server error',
      message: err.message
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.originalUrl} not found`
  });
});

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;

