/**
 * Security Testing Helper
 * Run this file to test various security aspects
 */

const http = require('http');
const url = require('url');

const BASE_URL = 'http://localhost:3000';

/**
 * Make a simple HTTP request and return response data
 */
async function makeRequest(method, path, data = {}) {
  return new Promise((resolve, reject) => {
    const parsedUrl = url.parse(BASE_URL + path);

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || 80,
      path: parsedUrl.path,
      method: method,
      headers: {
        'Content-Type': 'application/json',
      }
    };

    const req = http.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        try {
          resolve({ status: res.statusCode, body: JSON.parse(body) });
        } catch (e) {
          resolve({ status: res.statusCode, body });
        }
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    if (data && Object.keys(data).length > 0) {
      req.write(JSON.stringify(data));
    }

    req.end();
  });
}

/**
 * Test XSS Attempt - should be sanitized
 */
async function testXSS() {
  console.log('\n=== Testing XSS Protection ===');
  const maliciousInput = `<script>alert('XSS')</script><img src=x onerror=alert("XSS")>`;
  const payload = { email: maliciousInput, password: 'password123' };
  const response = await makeRequest('POST', '/api/login', payload);

  console.log('✓ Attempted XSS attack');
