  const hasErrorHandling = check(appContent.includes('next('), 'Express error handling middleware present');
  const has404Handler = check(appContent.includes('404'), '404 route handler exists');
  const hasStructuredErrors = check(appContent.includes('.error') && appContent.includes('.status('), 'Structured error responses used');

  console.log(`\n${colors.blue}📊 Summary:${colors.reset}`);
  const appChecks = [
    hasNodeEnvDefault,
    hasErrorHandling,
    has404Handler,
    hasStructuredErrors
  ].filter(Boolean).length;
  console.log(`Error handling validation: ${appChecks}/4 checks passed`);

  if (appChecks === 4) {
    console.log(`\n${colors.green}✓ app.js has secure error handling patterns${colors.reset}\n`);
  } else {
    console.log(`\n${colors.yellow}⚠️  Consider adding missing error handling${colors.reset}\n`);
  }

} else {
  console.log(`✗ app.js not found at ${appPath}\n`);
}

console.log(`${colors.blue}🔧 Validating requested security improvements...${colors.reset}`);

const securityPackages = [
  'helmet',
  'express-rate-limit',
  'xss-clean',
  'express-mongo-sanitize'
];

console.log('Checking if security dependencies are installed...\n');
let missingPackages = 0;
const packageJsonPath = path.join(__dirname, 'package.json');

if (fs.existsSync(packageJsonPath)) {
  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf-8'));
  const installedPackages = Object.keys(packageJson.dependencies || {});

  securityPackages.forEach(pkg => {
    const isInstalled = check(installedPackages.includes(pkg), `${pkg} is installed`);
    if (!isInstalled) missingPackages++;
  });

  if (missingPackages === 0) {
    console.log(`\n${colors.green}✓ All security dependencies are installed${colors.reset}\n`);
  } else {
    console.log(`\n${colors.yellow}⚠️  Install missing dependencies: npm install [${securityPackages.filter(p => !installedPackages.includes(p)).join(', ')}]${colors.reset}\n`);
  }
}

console.log(`${colors.blue}✓ Configuration validation complete${colors.reset}\n`);

